class Book::AccessImport
  Result = Struct.new(:accesses, :duplicate_index)

  def initialize(book, grants)
    @book, @grants = book, grants
  end

  def import
    return Result.new([], nil) if @grants.empty?

    user_ids = @grants.map { |grant| user_id_for(grant) }
    duplicate_index = rejection_index(user_ids)
    return Result.new([], duplicate_index) if duplicate_index

    begin
      accesses = insert_accesses(user_ids)
    rescue ActiveRecord::RecordNotUnique
      return Result.new([], rejection_index(user_ids) || 0)
    end

    accesses.each { |access| Book::AccessNotificationJob.perform_later(access) }
    Result.new(accesses, nil)
  end

  private
    def rejection_index(user_ids)
      existing_user_ids = @book.accesses.where(user_id: user_ids).pluck(:user_id).to_set
      seen_user_ids = Set.new

      @grants.each_with_index do |grant, index|
        return index unless valid_level?(level_for(grant))

        user_id = user_ids[index]
        return index if existing_user_ids.include?(user_id) || !seen_user_ids.add?(user_id)
      end

      nil
    end

    def insert_accesses(user_ids)
      attributes = @grants.each_with_index.map do |grant, index|
        { user_id: user_ids[index], level: level_for(grant) }
      end

      result = @book.accesses.insert_all!(attributes, returning: Access.column_names)
      accesses_by_user_id = result.to_a.index_by { |attributes| attributes["user_id"] }
      user_ids.map { |user_id| Access.instantiate(accesses_by_user_id.fetch(user_id)) }
    end

    def user_id_for(grant)
      Access.type_for_attribute("user_id").cast(grant[:user_id] || grant["user_id"])
    end

    def level_for(grant)
      grant[:level] || grant["level"]
    end

    def valid_level?(level)
      Access.levels.key?(level.to_s)
    end
end
EOF
