require "test_helper"

class Book::AccessImportQueryTest < ActiveSupport::TestCase
  setup do
    @book = Book.create!(title: "Roster #{SecureRandom.hex(4)}", everyone_access: false)
  end

  test "query counts" do
    users = [ users(:jz), users(:kevin), users(:david) ]
    grants = users.map { |user| { user_id: user.id, level: :reader } }

    assert_queries_count(2) { Book::AccessImport.new(@book, grants).import }

    @book.accesses.create!(user_id: users(:jason).id, level: :reader)
    dup_grants = users.map { |user| { user_id: user.id, level: :reader } } +
      [ { user_id: users(:jason).id, level: :reader } ]
    assert_queries_count(1) { Book::AccessImport.new(@book, dup_grants).import }

    bad_grants = [ { user_id: users(:jason).id, level: :wizard } ]
    assert_queries_count(1) { Book::AccessImport.new(@book, bad_grants).import }
  end
end
EOF
